  Batch(NativeAreaMaterialAction.Context c,ClientSession target,BattleSpellCatalog.FreezeAttackSpell spell,boolean world){this.c=c;this.target=target;this.spell=spell;this.world=world;lifetime=NativePlayerLifetime.of(c.hub);life=NativeSourceMaterialFirstLife.playerLife(NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(target,"timedStatus"),true),target,c);x=number(target,"positionX");y=number(target,"positionY");cx=number(c.pc,"positionX");cy=number(c.pc,"positionY");}
