 static void original(ClientSession pc,byte[] packet,BattleSpellCatalog.FreezeAttackSpell spell,boolean world)throws IOException {if(world)pc.nativeFreezeAcceptedOriginalWorld(packet,spell);else pc.nativeFreezeAcceptedOriginalBattle(packet,spell);}
 static void battle(ClientSession pc,byte[] packet,BattleSpellCatalog.FreezeAttackSpell spell)throws IOException{run(pc,packet,spell,false);}
